/**
 * Fixture bytes for linkedin-import.spec.ts.
 *
 * BASIC_EN_PDF_BASE64, OTHER_PDF_BASE64, and LOCALIZED_VI_PDF_BASE64 are the
 * same synthetic fixtures committed at
 * apps/web/test/import/linkedin/fixtures/{basic-en,other,localized-vi}.pdf
 * (docs/design/linkedin-import.md, "Tests"; ADR 0023), base64-encoded here
 * because this package runs in its own container with no access to the
 * apps/web workspace at proof time. No real LinkedIn PDF, or text copied
 * from one, appears anywhere in this repository.
 *
 * slowContentPdf builds a one-off hostile file in code, the same way
 * apps/web/test/import/linkedin/helpers/pdfBuilder.ts builds its own hostile
 * fixtures for unit tests, rather than committing it as a binary. The
 * design's "Security" section names a small file whose page content
 * decompresses into far more bytes than it reads as exactly what the
 * 15-second time cap defends against; this file is that shape, so the proof
 * below can show the cap firing in a real browser instead of only in a
 * Vitest run with an injected shorter limit.
 */
import { deflateSync } from 'node:zlib';

export const BASIC_EN_PDF_BASE64 = '';

export const OTHER_PDF_BASE64 = '';

export const LOCALIZED_VI_PDF_BASE64 = '';

type PdfObject = string | { dict: string; stream: Uint8Array };

const textEncoder = new TextEncoder();

function concatBytes(parts: readonly Uint8Array[]): Uint8Array {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/** A minimal single-generation PDF, adapted from
 * apps/web/test/import/linkedin/helpers/pdfBuilder.ts's buildPdf: object 1
 * must be the catalog. */
function buildPdf(objects: readonly PdfObject[]): Buffer {
  const parts: Uint8Array[] = [textEncoder.encode('%PDF-1.4\n')];
  let length = parts[0]!.length;
  const offsets: number[] = [];
  objects.forEach((object, index) => {
    offsets.push(length);
    const body = typeof object === 'string'
      ? textEncoder.encode(`${index + 1} 0 obj\n${object}\nendobj\n`)
      : concatBytes([
        textEncoder.encode(
          `${index + 1} 0 obj\n<< ${object.dict} `
          + `/Length ${object.stream.length} >>\nstream\n`,
        ),
        object.stream,
        textEncoder.encode('\nendstream\nendobj\n'),
      ]);
    parts.push(body);
    length += body.length;
  });
  const xref = [
    'xref',
    `0 ${objects.length + 1}`,
    '0000000000 65535 f ',
    ...offsets.map((offset) => `${String(offset).padStart(10, '0')} 00000 n `),
    'trailer',
    `<< /Size ${objects.length + 1} /Root 1 0 R >>`,
    'startxref',
    String(length),
    '%%EOF',
    '',
  ].join('\n');
  parts.push(textEncoder.encode(xref));
  return Buffer.from(concatBytes(parts));
}

/** `unit` repeated `times` times, by doubling: about log2(times) concats of
 * geometrically growing buffers rather than `times` small copies, so
 * building a several-hundred-MiB page body costs a handful of memcpys, not
 * millions of tiny ones. */
function repeatedBytes(unit: Uint8Array, times: number): Uint8Array {
  if (times <= 1) return unit;
  const half = repeatedBytes(unit, Math.floor(times / 2));
  const doubled = concatBytes([half, half]);
  return times % 2 === 0 ? doubled : concatBytes([doubled, unit]);
}

/** One page's compressed content stream: `repeats` copies of a six-number
 * `cm` operator. pdf.js's content-stream interpreter must still lex six
 * numbers and multiply a matrix for each repetition even though `cm` never
 * yields a text item, so this adds real interpreter time without ever
 * tripping read.ts's item or character caps. */
function slowPageStream(repeats: number): { dict: string; stream: Uint8Array } {
  const unit = textEncoder.encode('1 0 0 1 1 1 cm\n');
  const raw = repeatedBytes(unit, repeats);
  return { dict: '/Filter /FlateDecode', stream: deflateSync(raw) };
}

// read.ts's MAX_PAGES is 20; this uses every one of them, and the highest
// per-page repeat count that still leaves the whole file under read.ts's own
// 4 MiB size cap once compressed (DEFLATE cannot shrink a short repeating
// cycle much past roughly 500:1, a hard ceiling measured against this exact
// unit, well short of the "past 1 GiB" decompressed scale the design's
// "Security" section describes as the eventual, unbounded outcome).
const SLOW_PDF_PAGE_COUNT = 20;
const SLOW_PDF_OPERATOR_REPEATS_PER_PAGE = 6_000_000;

/**
 * A 20-page PDF with no text, only enough non-text operators that a real
 * pdf.js worker cannot finish reading it inside the 15-second cap (read.ts's
 * TIME_LIMIT_MS). Built fresh per call.
 */
export function slowContentPdf(): Buffer {
  const firstPage = 3;
  const kids = Array.from(
    { length: SLOW_PDF_PAGE_COUNT },
    (_, i) => `${firstPage + i * 2} 0 R`,
  ).join(' ');
  const objects: PdfObject[] = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    `<< /Type /Pages /Kids [${kids}] /Count ${SLOW_PDF_PAGE_COUNT} >>`,
  ];
  for (let i = 0; i < SLOW_PDF_PAGE_COUNT; i += 1) {
    objects.push(
      '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] '
      + `/Resources << >> /Contents ${firstPage + i * 2 + 1} 0 R >>`,
    );
    objects.push(slowPageStream(SLOW_PDF_OPERATOR_REPEATS_PER_PAGE));
  }
  return buildPdf(objects);
}
